function monthKey(offset=0){const d=new Date();d.setDate(1);d.setMonth(d.getMonth()+offset);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;}
function defaultMonth(choice){return choice==="Next month"?monthKey(1):monthKey(0);}
function getRosterSettings(){
 const c=rosterVisibilitySettings[selected]||(rosterVisibilitySettings[selected]={employeeFutureVisible:true,hrDefault:"Next month",employeeDefault:"Next month"});
 if(!hrRosterMonth)hrRosterMonth=defaultMonth(c.hrDefault);if(!employeeRosterMonth)employeeRosterMonth=defaultMonth(c.employeeDefault);return c;
}
function monthLabel(month){const [y,m]=month.split('-').map(Number);return new Date(y,m-1,1).toLocaleDateString('en',{month:'long',year:'numeric'});}
function shiftForEmployeeDate(employeeId,date){
 const published=shiftRoster.find(r=>r.companyId===selected&&r.employeeId===employeeId&&r.date===date&&r.status==='Published');
 if(published)return {shiftId:published.shiftId,source:'Published roster',status:'Published'};
 const assignment=shiftAssignments.filter(a=>a.companyId===selected&&a.employeeId===employeeId&&a.status==='Active'&&a.effectiveFrom<=date&&(!a.effectiveTo||a.effectiveTo>=date)).sort((a,b)=>b.effectiveFrom.localeCompare(a.effectiveFrom))[0];
 return assignment?{shiftId:assignment.shiftId,source:'Normal assignment',status:'Assigned'}:{shiftId:null,source:'No schedule',status:'Unassigned'};
}
