   <select id="hr-roster-employee-status"><option value="All">All roster statuses</option>${['Published','Draft','Mixed','No roster'].map(s=>`<option value="${s}" ${hrRosterEmployeeStatus===s?'selected':''}>${s}</option>`).join('')}</select>
