const roleConfig={superadmin:{name:"Platform Superadmin",email:"superadmin@next-hrms.test",landing:"superadmin",pages:["overview","superadmin","enrollment","companies","access","audit"]},company:{name:"Company Admin",email:"companyadmin@demo.test",landing:"companydashboard",pages:["companydashboard","employees","shifts","rosterreport","access","settings","attendance","leave","payroll","audit"]},hr:{name:"HR Manager",email:"hr@vtl-demo.test",companyId:"co-vtl",landing:"hrhome",pages:["hrhome","employees","shifts","rosterreport","attendance","leave","payroll","settings"]},manager:{name:"Department Manager",email:"manager@vtl-demo.test",companyId:"co-vtl",landing:"managerhome",pages:["managerhome","employees","attendance","leave"]},employee:{name:"Employee",email:"employee@vtl-demo.test",companyId:"co-vtl",landing:"employeehome",pages:["employeehome","employeeprofile","myroster","employeeleave"]}};
