function renderRoleNav(){const c=roleConfig[currentRole];const labels={overview:"▦ Platform overview",superadmin:"◇ Superadmin",enrollment:"＋ Company enrollment",companies:"▤ Companies",access:"♙ Users & roles",shifts:"◷ Shift management",companydashboard:"▦ Company dashboard",employees:"♧ Employees",attendance:"◷ Attendance",leave:"▣ Leave management",payroll:"＄ Payroll & reports",settings:"⚙ Company setup",audit:"≡ Audit trail",hrhome:"▦ HR Manager dashboard",managerhome:"▦ Department dashboard",employeehome:"▦ My workspace",employeeprofile:"♙ My Profile",employeeleave:"▣ My Leave",rosterreport:"▦ Monthly Shift & Roster",myroster:"▦ My Monthly Roster"};$("#nav").innerHTML=c.pages.map(pg=>`<button data-page="${pg}">${labels[pg]}</button>`).join("");$("#profile-name").textContent=c.name;$("#profile-email").textContent=currentEmail;$("#profile-avatar").textContent=c.name.split(" ").map(x=>x[0]).slice(0,2).join("");$("#active-role").textContent=c.name;}
