const renderers={overview,companydashboard,superadmin,enrollment,companies,access,employees,shifts:shiftManagement,rosterreport:monthlyRosterOverview,myroster:myRoster,attendance,leave,payroll,settings,audit,policyhistory,legacyhistory,hrhome:hrManagerHome,managerhome:managerHome,employeehome:employeeHome,employeeprofile:employeeProfile,employeeleave:employeeLeave};
function render(){enforceRolePage();enforceCompanyScope();renderRoleNav(); $("#title").textContent=({overview:"Overview",companydashboard:"Company dashboard",superadmin:"Superadmin",enrollment:"Company enrollment",companies:"Companies",access:"Users & access",employees:"Employees",shifts:"Shift management",attendance:"Attendance",leave:"Leave & approvals",payroll:"Payroll & reports",settings:"Company setup",audit:"Audit trail",policyhistory:"Policy history",legacyhistory:"Legacy employee history",employeeleave:"My Leave",employeehome:"My Workspace",employeeprofile:"My Profile",myroster:"My Monthly Roster"})[page];$$("[data-page]").forEach(b=>b.classList.toggle("active",b.dataset.page===page));$("#content").innerHTML=renderers[page]();bind()}
function go(p){page=p;render();scrollTo(0,0)}
