function saveSetupFields(){let c=D.companies.find(x=>x.id===selected)||D.companies[0];if(!setupValues[c.id])setupValues[c.id]={};$$("[data-setup-field]").forEach(el=>setupValues[c.id][el.dataset.setupField]=el.value.trim())}
