function modal(title,body,save){$("#modal").innerHTML=`<div class="modalback"><div class="modal"><div class="modalhead"><h2>${title}</h2><button data-close>×</button></div>${body}<div class="modalactions"><button class="btn" data-close>Cancel</button><button class="btn primary" data-save>Save demo change</button></div></div></div>`;$$("[data-close]").forEach(b=>b.onclick=()=>$("#modal").innerHTML="");$("[data-save]").onclick=()=>{if(save()!==false)$("#modal").innerHTML=""}}
function review(id){
 let l=D.leave.find(x=>x.id===id);if(!l)return;
 if(!canReviewLeave(l)){notify('This request is not awaiting your approval level.');return;}
 const level=l.status==='Pending Level 1 approval'?1:2;
 const roleName=level===1?'Reporting Manager':'HR Manager';
 modal(`Level ${level} review · ${roleName}`,`<p><b>${esc(l.employee)}</b> · ${esc(l.type)} · ${esc(l.dates)} · ${l.days} day(s)</p><p><b>Reason:</b> ${esc(l.reason||'Not recorded')}</p><div class="notice">${level===1?'If approved, this request moves to Level 2 — HR Manager.':'This is the final approval stage. Approval will confirm the leave and deduct the approved balance.'}</div><div class="field"><label>Decision</label><select id="l-decision"><option>Approved</option><option>Rejected</option><option>Return for correction</option></select></div><div class="field" style="margin-top:10px"><label>Review comment</label><textarea id="l-comment" rows="3" placeholder="Add a comment for the employee"></textarea></div>`,()=>{
  const decision=$('#l-decision').value,comment=$('#l-comment').value.trim(),now=new Date().toISOString();
  l.approvalSteps ||= [{level:1,role:'Reporting Manager',status:'Waiting'},{level:2,role:'HR Manager',status:'Waiting'}];
  const step=l.approvalSteps[level-1];step.status=decision==='Approved'?'Approved':decision==='Rejected'?'Rejected':'Returned';step.actor=persona;step.at=now;step.comment=comment;
  if(decision==='Rejected'){l.status='Rejected';if(level===1)l.approvalSteps[1].status='Not required';}
  else if(decision==='Return for correction'){l.status='Returned for correction';if(level===1)l.approvalSteps[1].status='Not required';}
  else if(level===1)l.status='Pending Level 2 approval';
  else {
   const b=(D.leaveBalances||[]).find(x=>x.employeeId===l.employeeId&&x.type===l.type);
   if(!b||b.remaining<l.days){notify('Cannot complete approval: sufficient recorded leave balance is not available.');step.status='Pending';delete step.actor;delete step.at;delete step.comment;return false;}
   b.used+=l.days;b.remaining-=l.days;l.balanceDeducted=true;l.status='Approved';
  }
  l.updatedAt=now;D.audit.unshift({time:now.slice(0,16),actor:persona,action:`Level ${level} leave review`,target:id,result:l.status+(comment?' · '+comment:'')});
  notify(level===1&&decision==='Approved'?'Level 1 approved. Sent to HR Manager for Level 2 review.':'Leave review saved.');go('leave');return true;
 });
}

